import csv
# Check RFC 4180 compliance
with open('outputs/t02_eurostat_raw.csv', 'r') as f:
    reader = csv.reader(f)
    header = next(reader)
    expected_cols = len(header)
    errors = []
    for i, row in enumerate(reader, 2):
        if len(row) != expected_cols:
            errors.append(f'Row {i}: {len(row)} columns, expected {expected_cols}')
    if errors:
        for e in errors[:5]:
            print(e)
    else:
        print(f'All {i} data rows have exactly {expected_cols} columns')
