import csv
# Check if indicator names match between selected and raw data
selected = {}
with open('outputs/t01_selected_indicators.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        selected[row['indicator_id'].strip()] = row['indicator_name'].strip()

raw_names = {}
with open('inputs/eurostat/eurostat_city_values_sample.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ind_id = row['indicator_id'].strip()
        if ind_id in selected:
            raw_names[ind_id] = row['indicator_name'].strip()

# Check for mismatches
for ind_id in selected:
    sel_name = selected[ind_id]
    raw_name = raw_names.get(ind_id, 'NOT IN RAW')
    if sel_name != raw_name:
        print(f'MISMATCH {ind_id}:')
        print(f'  Selected: {repr(sel_name)}')
        print(f'  Raw:      {repr(raw_name)}')

print('Done checking indicator names')
""}
